	vse.[description] AS [visit_search_engine],
	tgt.[visit_start_page_url],
	tgt.[visit_start_pagename],
	tgt.[visit_start_time_gmt],
	tgt.[weekly_visitor],
	tgt.[yearly_visitor],
	ma.*
FROM [Adobe].[hit_data] tgt
	LEFT JOIN [Adobe].[browser] br
		ON tgt.[browser] = br.[browser_id]
	LEFT JOIN [Adobe].[connection_type] ct
		ON tgt.[connection_type] = ct.[connection_type_id]
	LEFT JOIN [Adobe].[country] ctry
		ON tgt.[country] = ctry.[country_id]
	LEFT JOIN [Adobe].[languages] lng
		ON tgt.[language] = lng.[languages_id]
	LEFT JOIN [Adobe].[operating_systems] os
		ON tgt.[os] = os.[operating_systems_id]
	--LEFT JOIN [Adobe].[event] ev
	--	ON tgt.[post_event_list] = ev.[event_id]
	LEFT JOIN [Adobe].[search_engines] se
		ON tgt.[post_search_engine] =se.[search_engines_id]
	LEFT JOIN [Adobe].[resolution] res
		ON tgt.[resolution] = res.[resolution_id]
	LEFT JOIN [Adobe].[search_engines] vse
		ON tgt.[visit_search_engine] = vse.[search_engines_id]
	LEFT JOIN [Adobe].[mobile_attributes] ma
		ON tgt.[mobile_id] = ma.[mobile_id]
